package local.proxy.switcher;

import android.app.Activity;
import android.os.Bundle;
import android.provider.Settings;
import android.graphics.Color;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import java.util.ArrayList;

public class MainActivity extends Activity {
  LinearLayout root; TextView status, address, indicator; android.content.SharedPreferences prefs; ArrayList<Button> useButtons=new ArrayList<>(); ArrayList<String> useKeys=new ArrayList<>();
  int dp(float n){ return (int)(n*getResources().getDisplayMetrics().density+.5f); }
  void focusHighlight(Button b){ b.setOnFocusChangeListener((v,has)->{ if(has){ b.setBackgroundColor(Color.rgb(255,193,7)); b.setTextColor(Color.BLACK); } else if(useButtons.contains(b)){ refresh(); } else { b.setBackgroundColor(Color.rgb(100,100,100)); b.setTextColor(Color.WHITE); } }); }
  TextView text(String s,float size){ TextView t=new TextView(this); t.setText(s); t.setTextColor(Color.WHITE); t.setTextSize(size); t.setPadding(dp(12),dp(8),dp(12),dp(8)); return t; }
  @Override public void onCreate(Bundle b){ super.onCreate(b); prefs=getSharedPreferences("presets",0); build(); refresh(); }
  void build(){ root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setGravity(Gravity.CENTER_HORIZONTAL); root.setPadding(dp(48),dp(28),dp(48),dp(28)); root.setBackgroundColor(Color.rgb(20,20,20));
    LinearLayout header=new LinearLayout(this); header.setGravity(Gravity.CENTER_VERTICAL); TextView title=text("电视代理控制",28); indicator=text("●",38); indicator.setGravity(Gravity.CENTER); header.addView(title,new LinearLayout.LayoutParams(0,dp(64),1)); header.addView(indicator,new LinearLayout.LayoutParams(dp(100),dp(64))); root.addView(header,new LinearLayout.LayoutParams(-1,dp(70)));
    status=text("",22); Button offTop=new Button(this); offTop.setText("关闭代理"); offTop.setTextSize(13); focusHighlight(offTop); offTop.setOnClickListener(v->setProxy(":0")); LinearLayout statusRow=new LinearLayout(this); statusRow.setGravity(Gravity.CENTER_VERTICAL); statusRow.addView(status,new LinearLayout.LayoutParams(0,dp(62),1)); statusRow.addView(offTop,new LinearLayout.LayoutParams(dp(190),dp(62))); root.addView(statusRow,new LinearLayout.LayoutParams(-1,dp(68)));
    address=text("预设代理（填写后按“使用”切换）",20); root.addView(address,new LinearLayout.LayoutParams(-1,dp(48)));
    for(int i=0;i<4;i++) addPreset(i);
    setContentView(root); }
  void addPreset(int i){ LinearLayout row=new LinearLayout(this); row.setGravity(Gravity.CENTER_VERTICAL); EditText n=new EditText(this); n.setText(prefs.getString("name"+i,"")); n.setTextColor(Color.WHITE); n.setTextSize(18); n.setSingleLine(); n.setHint("设备备注"); EditText h=new EditText(this); h.setText(prefs.getString("host"+i,i==0?"192.168.3.11":"").replace('·','.')); h.setTextColor(Color.WHITE); h.setTextSize(18); h.setSingleLine(); h.setHint("IP"); EditText p=new EditText(this); p.setText(prefs.getString("port"+i,i==0?"1082":"")); p.setTextColor(Color.WHITE); p.setTextSize(18); p.setSingleLine(); p.setInputType(2); p.setHint("端口"); Button save=new Button(this); save.setText("保存"); save.setTextSize(14); Button use=new Button(this); use.setText("使用"); use.setTextSize(14); focusHighlight(save); focusHighlight(use); useButtons.add(use); useKeys.add(h.getText().toString().trim()+":"+p.getText().toString().trim()); Runnable saveIt=()->{ String host=h.getText().toString().trim().replace('·','.').replace('．','.').replace('。','.'), port=p.getText().toString().trim(); h.setText(host); prefs.edit().putString("name"+i,n.getText().toString().trim()).putString("host"+i,host).putString("port"+i,port).apply(); useKeys.set(i,host+":"+port); refresh(); Toast.makeText(this,"已保存第"+(i+1)+"组代理",Toast.LENGTH_SHORT).show(); }; save.setOnClickListener(v->saveIt.run()); use.setOnClickListener(v->{ saveIt.run(); setProxy(h.getText().toString().trim()+":"+p.getText().toString().trim()); }); row.addView(n,new LinearLayout.LayoutParams(0,dp(62),1.2f)); row.addView(h,new LinearLayout.LayoutParams(0,dp(62),1.8f)); row.addView(p,new LinearLayout.LayoutParams(0,dp(62),.9f)); row.addView(save,new LinearLayout.LayoutParams(dp(120),dp(62))); row.addView(use,new LinearLayout.LayoutParams(dp(120),dp(62))); root.addView(row); }
  String proxy(){ return Settings.Global.getString(getContentResolver(),"http_proxy"); }
  void refresh(){ String p=proxy(); boolean on=p!=null && p.length()>0 && !p.equals(":0") && !p.equals("null"); String label=""; if(on){ for(int i=0;i<4;i++){ String h=prefs.getString("host"+i,""); String po=prefs.getString("port"+i,""); if((h+":"+po).equals(p)){ label=prefs.getString("name"+i,""); break; } } } indicator.setTextColor(on?Color.rgb(60,210,80):Color.rgb(230,55,55)); status.setText(on?(label.length()>0?"正在使用："+label+"（"+p+"）":"状态：已启用（"+p+"）"):"状态：未启用"); address.setText(on?"HTTP代理清单："+p:"HTTP代理清单：未设置"); for(int i=0;i<useButtons.size();i++){ boolean selected=on && useKeys.get(i).equals(p); boolean focused=useButtons.get(i).hasFocus(); useButtons.get(i).setText(selected?"已选中":"使用"); useButtons.get(i).setTextColor(focused?Color.BLACK:(selected?Color.rgb(20,70,20):Color.WHITE)); useButtons.get(i).setBackgroundColor(focused?Color.rgb(255,193,7):(selected?Color.rgb(76,175,80):Color.rgb(100,100,100))); } }
  void setProxy(String p){ try { p=p.replace('·','.').replace('．','.').replace('。','.'); Settings.Global.putString(getContentResolver(),"http_proxy",p); Settings.Global.putString(getContentResolver(),"global_http_proxy_host",p.equals(":0")?"":p.substring(0,p.lastIndexOf(':'))); Settings.Global.putString(getContentResolver(),"global_http_proxy_port",p.equals(":0")?"0":p.substring(p.lastIndexOf(':')+1)); refresh(); Toast.makeText(this,"已更新代理设置",Toast.LENGTH_SHORT).show(); } catch(Exception e){ Toast.makeText(this,"权限不足：请用ADB授予WRITE_SECURE_SETTINGS",Toast.LENGTH_LONG).show(); } }
}
